    { insert = "MOTRMisc", cat = "MOTORS", sub = "MISC", desc = "Motor sounds not fitting another category in this list." },
    { insert = "MOTRSrvo", cat = "MOTORS", sub = "SERVO", desc = "Specifically servo motors, from robot, to radio controlled servos. Clean isolated servos." },
    { insert = "MOTRTurb", cat = "MOTORS", sub = "TURBINE", desc = "Turbines, water or air. That classic 'whine' power up and down are usually turbines. A jet engine is a turbine." },
    { insert = "MOVEActv", cat = "MOVEMENT", sub = "ACTIVITY", desc = "Crowds moving but also performing activities, cleaning, moving boxes. Clean recordings with no vocals. See MOVEMENT-HUMAN for Single activity." },
    { insert = "MOVEAnml", cat = "MOVEMENT", sub = "ANIMAL", desc = "Group animal movement, individual feet go to FOOTSTEPS-ANIMAL or FOOTSTEPS-HORSE. But think herds of grazing animals, stampedes." },
    { insert = "MOVECrea", cat = "MOVEMENT", sub = "CREATURE", desc = "Slithering Dragons, Gooey Zombie Movement." },
    { insert = "MOVECrwd", cat = "MOVEMENT", sub = "CROWD", desc = "Groups of people milling or walking. Usually mostly just recordings of group footsteps in real locations. No vocals. Compare to MOVEMENT-ACTIVITY." },
    { insert = "MOVEHmn", cat = "MOVEMENT", sub = "HUMAN", desc = "Movement of single human, aside from footsteps, standing, sitting, shuffe. Some overlap or confusion with FOOTSTEP-HUMAN or MOVEMENT-ACTIVITY." },
    { insert = "MOVEInsc", cat = "MOVEMENT", sub = "INSECT", desc = "Group insects, footsteps, movement, swarms, spiders, locusts. Swarms of flying insects here too, bees, flies. Overlap with ANIMALS-INSECT or AMBIENCE-INSECT." },
    { insert = "MOVEMisc", cat = "MOVEMENT", sub = "MISC", desc = "Movement sounds not fitting another category in this list." },
    { insert = "MOVEPres", cat = "MOVEMENT", sub = "PRESENCE", desc = "Very light movement, people in church adjusting, people on church pews. Again, recordings without vocals. Compare to MOVEMENT-ACTIVITY and MOVEMENT-CROWD." },
    { insert = "MUSCBell", cat = "MUSICAL", sub = "BELLS", desc = "Specifically musical bells, tuned bells, think Tubular bells or hand bells. See also the BELL category for non-musical uses. BELL-GONG is older and this is a better fit." },
    { insert = "MUSCBrass", cat = "MUSICAL", sub = "BRASS", desc = "Brass musical instruments, trumpets, tuba, french horn." },
    { insert = "MUSCChim", cat = "MUSICAL", sub = "CHIME", desc = "Wind chimes, bell trees, Tinkerbell type magic chimes." },
    { insert = "MUSCChor", cat = "MUSICAL", sub = "CHORAL", desc = "Choir pieces, choral, not for 'designed type vocally stuff'." },
    { insert = "MUSCExpr", cat = "MUSICAL", sub = "EXPERIMENTAL", desc = "Strange or wierdly modified instruments, exotic instruments, prepared instruments like a prepared piano." },
    { insert = "MUSCInst", cat = "MUSICAL", sub = "INSTRUMENT", desc = "Various instruments that don't have a home in the other MUSICAL categories." },
    { insert = "MUSCKeyd", cat = "MUSICAL", sub = "KEYED", desc = "Keyed Instruments, such as pianos and harpsichord. For synthesizer though see MUSICAL-SYNTHESIZED." },
    { insert = "MUSCLoop", cat = "MUSICAL", sub = "LOOP", desc = "For looping musical phrases, sampled loops." },
    { insert = "MUSCMisc", cat = "MUSICAL", sub = "MISC", desc = "Music sounds not fitting another category in this list. Hopefully rarely needed." },
    { insert = "MUSCPerc", cat = "MUSICAL", sub = "PERCUSSION", desc = "Drums and percussion, including deep timpani or big war drums. Mainly meant for true membrane instruments, also see MUSICAL-TUNED PERCUSSION" },
    { insert = "MUSCTnprc", cat = "MUSICAL", sub = "PERCUSSION TUNED", desc = "Tuned percussion mostly played with mallets, Xylophones, Vibraphones, etc." },
    { insert = "MUSCPrfm", cat = "MUSICAL", sub = "PERFORMANCE", desc = "A musical performance, or warm-up, a live musical act, a street musican, high school band. If a mixed ambience, look to AMBIENCE categories, like PUBLIC PLACE." },
    { insert = "MUSCPluck", cat = "MUSICAL", sub = "PLUCKED", desc = "Guitars, Banjos, Harps, instruments that are mainly plucked when played. See also MUSICAL-STRINGED." },
    { insert = "MUSCSmpl", cat = "MUSICAL", sub = "SAMPLE", desc = "Musical samples. Single triggered samples, not loops, which has its own subcategory here." },
    { insert = "MUSCShake", cat = "MUSICAL", sub = "SHAKEN", desc = "Shaken musical instruments, rattles, tamourines." },
    { insert = "MUSCSong", cat = "MUSICAL", sub = "SONG & PHRASE", desc = "Complete musical pieces, songs as ringtones, car music bys. See also MUSICAL-PERFORMANCE which is a better fit for 'live performances'." },
    { insert = "MUSCStngr", cat = "MUSICAL", sub = "STINGER", desc = "A short musical phrase or accent, like a horror 'string' sting. A big pitching cello note. But musical in nature." },
    { insert = "MUSCStr", cat = "MUSICAL", sub = "STRINGED", desc = "Bowed string instruments like violin, cello, viola. Harp probably now goes to MUSICAL-PLUCKED." },
    { insert = "MUSCSynth", cat = "MUSICAL", sub = "SYNTHESIZED", desc = "Synth samples, musical synth performances. Some overlap with MUSICAL-SAMPLE, but this meant for more than simple triggered samples." },
    { insert = "MUSCToy", cat = "MUSICAL", sub = "TOY", desc = "Toys that play musical phrases, also music boxes would go here." },
    { insert = "MUSCWind", cat = "MUSICAL", sub = "WOODWIND", desc = "Woodwind instruments like flute, oboe, bassoon, clarinet." },
    { insert = "NATDAval", cat = "NATURAL DISASTER", sub = "AVALANCHE", desc = "Composite big movements of sliding, falling earth, landslides, mudslides. This category often for big hollywood versions of these types of sound." },
    { insert = "NATDQuak", cat = "NATURAL DISASTER", sub = "EARTHQUAKE", desc = "Composite and complex earthquake rumbles and rattles. This category often for big hollywood versions of these types of sound." },
    { insert = "NATDMisc", cat = "NATURAL DISASTER", sub = "MISC", desc = "Natural Disaster sounds not fitting another category in this list." },
    { insert = "NATDTorn", cat = "NATURAL DISASTER", sub = "TORNADO", desc = "Composite tornado sounds, layered and created massive tornadoes. This category often for big hollywood versions of these types of sound." },
    { insert = "NATDTsun", cat = "NATURAL DISASTER", sub = "TSUNAMI", desc = "Composite tidal wave or tsunami scenes, layered and created. This category often for big hollywood versions of these types of sound." },
    { insert = "NATDThyp", cat = "NATURAL DISASTER", sub = "TYPHOON", desc = "Composite typhoons, cyclones or hurricanes. Massive swirling storms. This category often for big hollywood versions of these types of sound." },
    { insert = "NATDVolc", cat = "NATURAL DISASTER", sub = "VOLCANO", desc = "Composite big volcano eruptions. Lava, lava bombs, eruptions. This category often for big hollywood versions of these types of sound. See also GEOTHERMAL-LAVA." },
    { insert = "OBJBag", cat = "OBJECTS", sub = "BAG", desc = "Bags and purses, shopping bags, lunch bags. Really any bag, except Luggage which would go to OBJECTS-LUGGAGE." },
    { insert = "OBJBook", cat = "OBJECTS", sub = "BOOK", desc = "Books, magazines, sounds relating to these. Handling particularly. Some overlap or confusion with PAPER-HANDLE." },
    { insert = "OBJCoin", cat = "OBJECTS", sub = "COIN", desc = "Coins land, toss, drop, handle. Coins being counted, sorted. A bag of coins." },
    { insert = "OBJCont", cat = "OBJECTS", sub = "CONTAINER", desc = "Boxes, tupperware, jewelry boxes, things that hold things, lids, handling, opens and closes." },
    { insert = "OBJFash", cat = "OBJECTS", sub = "FASHION", desc = "Shoes, belts, clothes, actions involding fashion objects. Makeup, lipstick, etc. Some overlap possible with CLOTH categories. See also OBJECTS-JEWELRY. And OBJECTS-BAG." },
    { insert = "OBJFurn", cat = "OBJECTS", sub = "FURNITURE", desc = "Chairs movement, couch movement, things like that. Wood chair creaks could go in WOOD-FRICTION." },
    { insert = "OBJGrdn", cat = "OBJECTS", sub = "GARDEN", desc = "Flower pots, bird feeders, things that you might find and use in a garden. See also TOOLS-GARDEN and MACHINES-GARDEN." },
    { insert = "OBJGym", cat = "OBJECTS", sub = "GYM", desc = "Objects found in a fitness center or school gym, maybe a yoga mat, dumbells. See also MACHINES-GYM." },
    { insert = "OBJHsehld", cat = "OBJECTS", sub = "HOUSEHOLD", desc = "Cleaning products, hangers, towel racks, things around the house that don't fit somewhere else." },
    { insert = "OBJJewl", cat = "OBJECTS", sub = "JEWELRY", desc = "Bracelets, necklaces, rings." },
    { insert = "OBJKey", cat = "OBJECTS", sub = "KEYS", desc = "Keys jingling, keys movement in lock." },
    { insert = "OBJLug", cat = "OBJECTS", sub = "LUGGAGE", desc = "Suitcases, luggage related sounds, handling, opening, packing." },
    { insert = "OBJMed", cat = "OBJECTS", sub = "MEDICAL", desc = "Common objects in hospital or medical office." },
    { insert = "OBJMisc", cat = "OBJECTS", sub = "MISC", desc = "Object sounds not fitting another category in this list." },
    { insert = "OBJOffc", cat = "OBJECTS", sub = "OFFICE", desc = "Things found in an office, staplers, paper cutter etc. Not machines like a printer which would go in MACHINES-OFFICE." },
    { insert = "OBJPack", cat = "OBJECTS", sub = "PACKAGING", desc = "Items commonly used in packaging or packing, so bubblewrap, styrofoam, labels, food packaging." },
    { insert = "OBJTape", cat = "OBJECTS", sub = "TAPE", desc = "Tape and other tacky sticky type sounds as well. Velcro probably better into CLOTH-RIP as that matches the 'sound' better." },
    { insert = "OBJUmbr", cat = "OBJECTS", sub = "UMBRELLA", desc = "Umbrella opens and closes. Not for rain on umbrella, which would go in RAIN-CLOTH." },
    { insert = "OBJWhled", cat = "OBJECTS", sub = "WHEELED", desc = "Non-motorized wheeled carts and dollies. Shopping cart, food cart, baggage cart, baby stroller, dolly, wheelchairs." },
    { insert = "OBJWrite", cat = "OBJECTS", sub = "WRITING", desc = "Any writing object or performance of writing on any surface. Pens, pencils, crayons, markers." },
    { insert = "OBJZipr", cat = "OBJECTS", sub = "ZIPPER", desc = "Pant zippers, bag zippers, luggage zippers." },
    { insert = "PAPRFltr", cat = "PAPER", sub = "FLUTTER", desc = "Paper and Cardboard. Tossing a group of pages or a book in the air, money flutters as it falls to the ground. Confetti." },
    { insert = "PAPRFric", cat = "PAPER", sub = "FRICTION", desc = "Paper and Cardboard. Sliding paper or scraping paper." },
    { insert = "PAPRHndl", cat = "PAPER", sub = "HANDLE", desc = "Paper and Cardboard. Page turns, magazine handling. Books dropping. Handling paper money. Some overlap or confusion with OBJECTS-BOOK." },
    { insert = "PAPRImpt", cat = "PAPER", sub = "IMPACT", desc = "Paper and Cardboard. Heavy paper hits, a rolled up newspaper thwack, a magazine hitting something." },
    { insert = "PAPRMisc", cat = "PAPER", sub = "MISC", desc = "Paper and Cardboard. Paper sounds not fitting another category in this list." },
    { insert = "PAPRRip", cat = "PAPER", sub = "RIP", desc = "Paper and Cardboard. Ripping paper, paper tears." },
    { insert = "PAPRTonl", cat = "PAPER", sub = "TONAL", desc = "Paper and Cardboard. Not very common, but tonal paper sounds." },
    { insert = "PLASBrk", cat = "PLASTIC", sub = "BREAK", desc = "Plastic breaking, crunches, rips, shatters." },
    { insert = "PLASCrsh", cat = "PLASTIC", sub = "CRASH & DEBRIS", desc = "Plastic crashing, groups items falling, group destruction, plastic debris." },
    { insert = "PLASFric", cat = "PLASTIC", sub = "FRICTION", desc = "Plastic friction, such as scrapes, creaks, squeaks, screeching." },
    { insert = "PLASHndl", cat = "PLASTIC", sub = "HANDLE", desc = "Plastic handling, handling a toy or remote control. Some overlap with PLASTIC-MOVEMENT possible." },
    { insert = "PLASImpt", cat = "PLASTIC", sub = "IMPACT", desc = "Plastic item impact. Hit, drop, big plastic impacts where item does not break. Dropping a plastic object." },
    { insert = "PLASMisc", cat = "PLASTIC", sub = "MISC", desc = "Plastic sounds not fitting another category in this list." },
    { insert = "PLASMvmt", cat = "PLASTIC", sub = "MOVEMENT", desc = "Plastic movement, dragging plastic or drag on plastic, rattles, shakes. See also PLASTIC-HANDLE." },
    { insert = "PLASTonl", cat = "PLASTIC", sub = "TONAL", desc = "Plastic tonal sounds, with a musical quality. Probably pretty rare." },
    { insert = "RAINClth", cat = "RAIN", sub = "CLOTH", desc = "Rain on cloth, like a person's clothes, or more likely a patio umbrella, awning." },
    { insert = "RAINConc", cat = "RAIN", sub = "CONCRETE", desc = "Rain on asphalt or concrete or patio tile. Rain on a hard slappy solid surface." },
