    { insert = "RAINGlas", cat = "RAIN", sub = "GLASS", desc = "Rain on a glass roof like a sunroof, or rain blown against a window as well." },
    { insert = "RAINInt", cat = "RAIN", sub = "INTERIOR", desc = "Interior recordings of Rain, from inside house or barn, or vehicle." },
    { insert = "RAINMetl", cat = "RAIN", sub = "METAL", desc = "Rain on a metal surface, so exterior rain on a car, or metal sheet, metal roof." },
    { insert = "RAINPlas", cat = "RAIN", sub = "PLASTIC", desc = "Rain on plastic or vinyl surfaces, like a grill cover, or a plastic shed." },
    { insert = "RAINVege", cat = "RAIN", sub = "VEGETATION", desc = "Rain on plants, leaves and grass. Jungle or tropical rain on plant leaves." },
    { insert = "RAINWatr", cat = "RAIN", sub = "WATER", desc = "Rain on water, puddles, lakes, ponds." },
    { insert = "RAINWood", cat = "RAIN", sub = "WOOD", desc = "Rain on wood surfaces, so a deck for example." },
    { insert = "ROBTMisc", cat = "ROBOTS", sub = "MISC", desc = "Robot sounds not fitting another category in this list." },
    { insert = "ROBTMvmt", cat = "ROBOTS", sub = "MOVEMENT", desc = "Complex robot movement, servos, possible robot hovering and flying. See also MOTORS-SERVO." },
    { insert = "ROBTVox", cat = "ROBOTS", sub = "VOCAL", desc = "Droid and robot vocals, R2D2 would go here. Any manner of vocalizing robot. More expressive than a beep/UI. Robot language." },
    { insert = "ROCKBrk", cat = "ROCKS", sub = "BREAK", desc = "Rock cracks, breaks, rips or shatters. More isolated and singular cracks and breaks." },
    { insert = "ROCKCrsh", cat = "ROCKS", sub = "CRASH & DEBRIS", desc = "Rock crashes and debris, so a huge rock crash, collapse. Or isolated debris. See also NATURAL DISASTER-AVALANCHE." },
    { insert = "ROCKFric", cat = "ROCKS", sub = "FRICTION", desc = "Rock creaks, scrapes... the stress of rock about to break." },
