    { insert = "ROCKImpt", cat = "ROCKS", sub = "IMPACT", desc = "Rock falling, dropping without breaking, or something hit with a rock, a big rock impact." },
    { insert = "ROCKMisc", cat = "ROCKS", sub = "MISC", desc = "Rock sounds not fitting another category in this list." },
    { insert = "ROCKMvmt", cat = "ROCKS", sub = "MOVEMENT", desc = "Rock dragging, or dragging across a rock surface, rocks shaking or rattling. See also ROCKS-HANDLE." },
    { insert = "ROCKTonl", cat = "ROCKS", sub = "TONAL", desc = "Tonal rocks, probably pretty rare. Singing rocks." },
    { insert = "ROPECreak", cat = "ROPE", sub = "CREAK", desc = "Rope stretches and creaks, people hanging from nooses.. Ship rope creaks. Tension of rope stretches." },
    { insert = "ROPEHndl", cat = "ROPE", sub = "HANDLE", desc = "Rope handling, tying knots, rigging up a ship sail. Possible overlap with ROPE-MOVEMENT." },
    { insert = "ROPEImpt", cat = "ROPE", sub = "IMPACT", desc = "Rope impacts, tossing ropes to ground, ropes banging violently in the wind. Possible overlap with ROPE-MOVEMENT." },
    { insert = "ROPEMisc", cat = "ROPE", sub = "MISC", desc = "Rope sounds not fitting another category in this list." },
    { insert = "ROPEMvmt", cat = "ROPE", sub = "MOVEMENT", desc = "Ropes zuzzing, moving across objects, zipline. See also ROPE-HANDLE." },
    { insert = "RUBRCrsh", cat = "RUBBER", sub = "CRASH & DEBRIS", desc = "Rubber items crashing, or rubber debris landing." },
    { insert = "RUBRFric", cat = "RUBBER", sub = "FRICTION", desc = "Rubber squeaks, balloon squeaks, a rubber shoe squeak." },
    { insert = "RUBRHndl", cat = "RUBBER", sub = "HANDLE", desc = "Rubber handling, rubber objects being manipulated or handled. Some overlap with RUBBER-MOVEMENT" },
    { insert = "RUBRImpt", cat = "RUBBER", sub = "IMPACT", desc = "Rubber impacts, drops, bounces. Hitting a balloon or rubber ball." },
    { insert = "RUBRMisc", cat = "RUBBER", sub = "MISC", desc = "Rubber sounds not fitting another category in this list." },
    { insert = "RUBRMvmt", cat = "RUBBER", sub = "MOVEMENT", desc = "Rubber movement, dragging rubber or drag on rubber. Rubber flapping. See also RUBBER-HANDLE." },
    { insert = "RUBRTonl", cat = "RUBBER", sub = "TONAL", desc = "Rubber movement with a tonal quality, a musical quality." },
    { insert = "SCIAlrm", cat = "SCIFI", sub = "ALARM", desc = "Overly futuristic alarms, the kind you're hear on a spaceship" },
    { insert = "SCICmpt", cat = "SCIFI", sub = "COMPUTER", desc = "Use Sci-Fi for overtly 'science fiction' type computer sounds, a very futuristic computer. Some overlap with USER INTERFACE." },
    { insert = "SCIDoor", cat = "SCIFI", sub = "DOOR", desc = "That Star-Trek type door. Spaceship doors." },
    { insert = "SCIEnrg", cat = "SCIFI", sub = "ENERGY", desc = "Energy particles, vortexes, transporters, holograms, force fields." },
    { insert = "SCIImpt", cat = "SCIFI", sub = "IMPACT", desc = "A bolt of SciFi energy, a hi-tech energy impact, more futuristic than just an explosion. Overlap with DESIGNED-IMPACT." },
    { insert = "SCIMach", cat = "SCIFI", sub = "MACHINE", desc = "Future technology machines, transporters, food replicators." },
    { insert = "SCIMech", cat = "SCIFI", sub = "MECHANISM", desc = "An overly sci-fi sounding gizmo or mechanism. Little unfolding robot or something like that. Similar to MACHINE-MECHANISM but more SciFi." },
    { insert = "SCIMisc", cat = "SCIFI", sub = "MISC", desc = "SCI-FI sounds not fitting another category in this list." },
    { insert = "SCIRetro", cat = "SCIFI", sub = "RETRO", desc = "Cheesy sci-fi sounds, like from The Jetsons, The Day the Earth Stood Still. Old TV or film sci-fi sounds." },
    { insert = "SCIShip", cat = "SCIFI", sub = "SPACESHIP", desc = "Spaceships here, your best Enterprise and Tie Fighter rip-offs! See also SCIFI-VEHICLE for non-spaceships." },
    { insert = "SCIVeh", cat = "SCIFI", sub = "VEHICLE", desc = "Various sci-fi vehicles, like a moon rover, landspeeder, speeder bike, hoverboard, podracer. See also SCIFI-SPACESHIP." },
    { insert = "SCIWeap", cat = "SCIFI", sub = "WEAPON", desc = "Lightsabers, exotic sci-fi weapons. Not a 'blaster' which would go in LASERS-GUN." },
    { insert = "SNOWCrsh", cat = "SNOW", sub = "CRASH & DEBRIS", desc = "Snow big crashes, a big fall of snow, a roof full of snow collapsing. See also NATURAL DISASTER-AVALANCE for the extreme version of this." },
    { insert = "SNOWFric", cat = "SNOW", sub = "FRICTION", desc = "Snow scrapes, squeaks. Skiing on snow, sledding." },
    { insert = "SNOWHndl", cat = "SNOW", sub = "HANDLE", desc = "Snow being handled, a snowball being formed, etc. Digging out of show with your hands. Some overlap with SNOW-MOVEMENT." },
    { insert = "SNOWImpt", cat = "SNOW", sub = "IMPACT", desc = "A big impact of snow, like a roof full of snow falling. Or smaller like a snowball. Jumping into a pile of snow." },
    { insert = "SNOWMisc", cat = "SNOW", sub = "MISC", desc = "Snow sounds not fitting another category in this list." },
    { insert = "SNOWMvmt", cat = "SNOW", sub = "MOVEMENT", desc = "Dragging something through snow, rolling in snow. See also SNOW-HANDLE." },
    { insert = "SPRTCourt", cat = "SPORTS", sub = "COURT", desc = "Sports played on a court indoors or out, such a basketball, tennis." },
    { insert = "SPRTField", cat = "SPORTS", sub = "FIELD", desc = "Sports played on a field outdoors such as soccer and football." },
    { insert = "SPRTGym", cat = "SPORTS", sub = "GYM", desc = "Sports played or performed primarily in a gym and/or ring, such as boxing, wrestling, gymnastics. See also SPORTS-INDOOR." },
    { insert = "SPRTIndor", cat = "SPORTS", sub = "INDOOR", desc = "Various indoor sports not able to be categorized elsewhere." },
    { insert = "SPRTMisc", cat = "SPORTS", sub = "MISC", desc = "Sport sounds not fitting another category in this list." },
    { insert = "SPRTSkate", cat = "SPORTS", sub = "SKATE", desc = "Wheeled skating sports like skateboarding or roller skating, rollerblading." },
    { insert = "SPRTTrck", cat = "SPORTS", sub = "TRACK & FIELD", desc = "Track and field sports, as in running, long jump, pole vault. Think common summer Olympic games." },
    { insert = "SPRTWatr", cat = "SPORTS", sub = "WATER", desc = "Sports played in or on water, swimming, diving. Aquatic sports." },
    { insert = "SPRTWntr", cat = "SPORTS", sub = "WINTER", desc = "Sports on snow or ice such as hockey, ice skating, snowboard and skiing." },
    { insert = "SWSH", cat = "SWOOSHES", sub = "SWISH", desc = "A swish is smaller than a Whoosh. Arm Swishes, Sword Swishes. Small objects make Swishes." },
    { insert = "WHSH", cat = "SWOOSHES", sub = "WHOOSH", desc = "A whoosh is larger than a swish. A large object would make a Whoosh. Tanks flying over your head, or an asteroid by. See also DESIGNED-WHOOSH for very stylized whooshes." },
    { insert = "TOOLGrdn", cat = "TOOLS", sub = "GARDEN", desc = "Hand tools used in a garden, rakes, hoes, etc. Also see MACHINES-GARDEN for powered machines. See also OBJECTS-GARDEN for non-tools." },
