    { insert = "TOOLMisc", cat = "TOOLS", sub = "MISC", desc = "Tool sounds not fitting another category in this list." },
    { insert = "TOOLPneu", cat = "TOOLS", sub = "PNEUMATIC", desc = "Air tools, such as jackhammers, air ratchets, nail guns. The air-wrench sound in a tire shop." },
    { insert = "TOOLPowr", cat = "TOOLS", sub = "POWER", desc = "Tools that require power. A sander, electric drill, dremel tool, circular saw." },
    { insert = "TOYElec", cat = "TOYS", sub = "ELECTRONIC", desc = "Remote controlled car, slot cars. Any kids toy that required power. See also AIRCRAFT-REMOTE CONTROLLED." },
    { insert = "TOYMech", cat = "TOYS", sub = "MECHANICAL", desc = "Wind up robots, things like that. Toys with some mechanism or mechanical component." },
    { insert = "TOYMisc", cat = "TOYS", sub = "MISC", desc = "Toy sounds not fitting another category in this list." },
    { insert = "TRNBrake", cat = "TRAINS", sub = "BRAKE", desc = "Screeching metalic train brake wheels, subway brakes. Usually a piercing sound." },
    { insert = "TRNClak", cat = "TRAINS", sub = "CLACK", desc = "Train clacks isolated, constant clacking of trains passing or running." },
    { insert = "TRNDoor", cat = "TRAINS", sub = "DOOR", desc = "Train doors, sliding doors in passenger or freight trains. Some overlap with general DOORS category and possibly VEHICLES-DOOR." },
    { insert = "TRNDiesl", cat = "TRAINS", sub = "DIESEL", desc = "Freight trains, large commercial diesel locomotives." },
    { insert = "TRNElec", cat = "TRAINS", sub = "ELECTRIC", desc = "Commuter trains, elevated trains, light rail, SUBWAYS have their own category." },
    { insert = "TRNHspd", cat = "TRAINS", sub = "HIGH SPEED", desc = "Hi-Tech trains, Maglev, monorails, Hyperloops, bullet trains." },
    { insert = "TRNHorn", cat = "TRAINS", sub = "HORN", desc = "Train horns, subway horns. A steam train whistle would likely go into WHISTLES-MECHANICAL." },
    { insert = "TRNInt", cat = "TRAINS", sub = "INTERIOR", desc = "Interior trains, from Diesel to Commuter, onboard train sounds." },
