    { insert = "TRNMisc", cat = "TRAINS", sub = "MISC", desc = "Train sounds not fitting another category in this list." },
    { insert = "TRNSteam", cat = "TRAINS", sub = "STEAM", desc = "Old steam powered trains, big smoke stack chugs." },
    { insert = "TRNSbwy", cat = "TRAINS", sub = "SUBWAY", desc = "Subways, overtly 'underground' sounding trains, above group city trains probably best in TRAINS-ELECTRIC" },
    { insert = "TRNTram", cat = "TRAINS", sub = "TRAM", desc = "Trolleys, cable cars trams and streetcars. A Tram is 'pulled' along a cable, so not self-powered. An electric tram would go to TRAINS-ELECTRIC." },
    { insert = "UIAlert", cat = "USER INTERFACE", sub = "ALERT", desc = "An alert tone or chime or notification. Something that gets Attention of User, startup chimes." },
    { insert = "UIBeep", cat = "USER INTERFACE", sub = "BEEP", desc = "Interface beeps, beeps while interacting with various technology, phones, computers. Also see BEEPS category." },
    { insert = "UIClick", cat = "USER INTERFACE", sub = "CLICK", desc = "Typing clicks, button press clicks, response to input." },
    { insert = "UIData", cat = "USER INTERFACE", sub = "DATA", desc = "User interface calculations, scanning, thinking, text displayed on screen. Screen gak or garble." },
    { insert = "UIGlitch", cat = "USER INTERFACE", sub = "GLITCH", desc = "On Screen Glitches or Static. Malfunctioning computer or OS." },
    { insert = "UIMisc", cat = "USER INTERFACE", sub = "MISC", desc = "User Interface sounds not fitting another category in this list." },
    { insert = "UIMvmt", cat = "USER INTERFACE", sub = "MOTION", desc = "User interface slides, swipes, scrolls. Open, Close, Appear, DIsappear." },
    { insert = "VEGEGras", cat = "VEGETATION", sub = "GRASS", desc = "Individual movement of grass elements in a studio or exterior environment." },
    { insert = "VEGELeaf", cat = "VEGETATION", sub = "LEAVES", desc = "Individual movement of leaf elements in a studio or exterior environment. Jumping into a pile of leaves." },
    { insert = "VEGEMisc", cat = "VEGETATION", sub = "MISC", desc = "Vegetation and Foliage sounds not fitting another category in this list." },
    { insert = "VEGETree", cat = "VEGETATION", sub = "TREE", desc = "Individual movement of tree and branch elements in a studio or exterior environment." },
    { insert = "VEHAlrm", cat = "VEHICLES", sub = "ALARM", desc = "Not sirens, but just Car alarms, car alarm arm and disarm chirps." },
    { insert = "VEHAntq", cat = "VEHICLES", sub = "ANTIQUE", desc = "Very old vehicles, such a Model A, Model T. Mainly cars, but possible other very old vehicles, trucks, tractors." },
    { insert = "VEHAtv", cat = "VEHICLES", sub = "ATV", desc = "All-Terrain Vehicle, three and four-wheelers, dune buggies, side by side." },
    { insert = "VEHBike", cat = "VEHICLES", sub = "BICYCLE", desc = "Bicycles, recumbent bikes, unicycles too. Any manner of pedal powered bicycle." },
    { insert = "VEHBrake", cat = "VEHICLES", sub = "BRAKE", desc = "Brake squeals and screeches of all kinds. TRAINS-BRAKE has its own category." },
    { insert = "VEHBus", cat = "VEHICLES", sub = "BUS", desc = "City buses, school buses, Greyhound buses." },
    { insert = "VEHCar", cat = "VEHICLES", sub = "CAR", desc = "All cars except overtly antique... add ERA to metadata to make searches easier. 1950s, 1960s..." },
    { insert = "VEHCnst", cat = "VEHICLES", sub = "CONSTRUCTION", desc = "Cranes, bulldozers, paving vehicles, any construction related vehicle goes here." },
    { insert = "VEHDoor", cat = "VEHICLES", sub = "DOOR", desc = "Car, van, truck. Their doors all go here." },
    { insert = "VEHElec", cat = "VEHICLES", sub = "ELECTRIC", desc = "Electric golf carts, electric scooters, electric cars. A Tesla. Any variety of electric vehicle, even electric motorcycles." },
    { insert = "VEHEmrg", cat = "VEHICLES", sub = "EMERGENCY", desc = "Specifically emegency vehicles like Firetrucks, Ambulances, Police cars. Isolated sirens would go still to VEHICLES-SIREN." },
    { insert = "VEHFarm", cat = "VEHICLES", sub = "FARM", desc = "I'd put farm tractors here, Some overlap possibly with CONSTRUCTION vehicles. A riding lawn mower would best to MACHINES-GARDEN maybe." },
    { insert = "VEHFrght", cat = "VEHICLES", sub = "FREIGHT", desc = "Big Rigs, Lorry, Semi-truck, U-Haul trucks, not for TRAINS, which have their own category." },
    { insert = "VEHBy", cat = "VEHICLES", sub = "GENERIC BY", desc = "Generic or general vehicle pass bys, not 'traffic'. Bys for a specific car go with that car. For group passbys use AMBIENCE-TRAFFIC." },
    { insert = "VEHHorn", cat = "VEHICLES", sub = "HORN", desc = "Specifically car and vehicles horns. BOATS-HORNS and TRAINS-HORN have their own category. Fog horn would go into HORNS-AIR." },
    { insert = "VEHInt", cat = "VEHICLES", sub = "INTERIOR", desc = "Interior recordings (ambiences) for car, truck, van interiors, from passenger cars, to back of a moving truck, riding inside a bus." },
    { insert = "VEHJalop", cat = "VEHICLES", sub = "JALOPY", desc = "Backfiring, poorly running vehicle. False starts, sputtering... In foreign language translate to MALFUNCTIONING. See also CARTOON-VEHICLE." },
    { insert = "VEHMech", cat = "VEHICLES", sub = "MECHANISM", desc = "Various mechanisms on a vehicle, like seatbelts, window cranks, door locks." },
    { insert = "VEHMil", cat = "VEHICLES", sub = "MILITARY", desc = "Overtly military ground vehicles. Tanks and military trucks for example. Armored Personnel Carriers, military Jeeps. See also AIRCRAFT-MILITARY and BOATS-MILITARY." },
    { insert = "VEHMisc", cat = "VEHICLES", sub = "MISC", desc = "Vehicles sounds not fitting another category in this list." },
    { insert = "VEHMoto", cat = "VEHICLES", sub = "MOTORCYCLE", desc = "Scooters, Motorcycles, Vespas, Motocross… All things 2 wheeled and powered. ATV goes to VEHICLES-ATV." },
    { insert = "VEHRace", cat = "VEHICLES", sub = "RACING", desc = "Racing cars or drag racing cars. Indy and Formula 1 cars, monster trucks, BOATS-RACING has its own category." },
    { insert = "VEHSirn", cat = "VEHICLES", sub = "SIREN", desc = "Police, Firetruck, Ambulance sirens. Any vehicle siren. See also VEHICLES-EMERGENCY if engine sounds are present also." },
    { insert = "VEHSkid", cat = "VEHICLES", sub = "SKID", desc = "Tire skids, peel-outs. Other tire sounds go in VEHICLES-TIRES." },
    { insert = "VEHSusp", cat = "VEHICLES", sub = "SUSPENSION", desc = "Suspension squeaks and rattles, for any car, truck, semi. Suspensions springs. A car or truck on a very rough road." },
    { insert = "VEHTire", cat = "VEHICLES", sub = "TIRE", desc = "Tire rolls on various surfaces, tire whines, no engine sounds, isolated tire sounds. A flat tire flop." },
    { insert = "VEHTruck", cat = "VEHICLES", sub = "TRUCK VAN & SUV", desc = "Passenger Trucks, pickup trucks, Vans and SUVs. Commercial trucks go in VEHICLES-FREIGHT." },
    { insert = "VEHUtil", cat = "VEHICLES", sub = "UTILITY", desc = "Golf carts, cushmans, traffic, gator, small motorized utility vehicles." },
    { insert = "VEHWagn", cat = "VEHICLES", sub = "WAGON", desc = "Old wood wagon, horse drawn carts, carriages, buggies. A Stagecoach." },
    { insert = "VEHWndw", cat = "VEHICLES", sub = "WINDOW", desc = "Powered windows for any vehicles, crank windows should go in VEHICLES-MECHANISM." },
    { insert = "VOXAlien", cat = "VOICES", sub = "ALIEN", desc = "Weird alien vocals here." },
    { insert = "VOXBaby", cat = "VOICES", sub = "BABY", desc = "Very young babies through toddler, non-word vocals, cut vocals." },
    { insert = "VOXCheer", cat = "VOICES", sub = "CHEER", desc = "A single person cheering. For a group use CROWDS-CHEERING." },
    { insert = "VOXChld", cat = "VOICES", sub = "CHILD", desc = "Various vocals for a child or a teenager. For non-discernible vocals for a very young child use VOICES-BABY." },
    { insert = "VOXCry", cat = "VOICES", sub = "CRYING", desc = "A single person crying." },
    { insert = "VOXEfrt", cat = "VOICES", sub = "EFFORTS", desc = "A single fight and vocal efforts, single grunts, and things like that. Boxing match vocals, tennis grunts." },
    { insert = "VOXFem", cat = "VOICES", sub = "FEMALE", desc = "Any generic female vocal or dialog or misc vocal that doesn't fit somewhere else." },
    { insert = "VOXFutz", cat = "VOICES", sub = "FUTZED", desc = "P.A. Speakers, Airport announcements, Hospital announcements." },
    { insert = "VOXHist", cat = "VOICES", sub = "HISTORICAL", desc = "For storing famous speeches, famous news broadcasts, presidential speeches." },
    { insert = "VOXLaff", cat = "VOICES", sub = "LAUGH", desc = "A single person laughing." },
    { insert = "VOXMale", cat = "VOICES", sub = "MALE", desc = "Any generic male vocal or dialog or misc vocal that doesn't fit somewhere else." },
    { insert = "VOXMisc", cat = "VOICES", sub = "MISC", desc = "The Voice category is for single voices. Groups of people go into the CROWDS categories." },
    { insert = "VOXReac", cat = "VOICES", sub = "REACTION", desc = "A single Ooo or Aah and things of that nature." },
    { insert = "VOXScrm", cat = "VOICES", sub = "SCREAM", desc = "A single scream or yell, battle cry, agonizing death." },
    { insert = "VOXSing", cat = "VOICES", sub = "SINGING", desc = "A single voice singing, a child singing. For a crowd, use CROWDS-SINGING" },
    { insert = "VOXWhsp", cat = "VOICES", sub = "WHISPER", desc = "A single whispering voice. The crowd equivalent would be CROWDS-QUIET." },
    { insert = "WATRBubl", cat = "WATER", sub = "BUBBLES", desc = "Single or continuous bubbles. Water boiling on a stove, fish tank bubbles." },
    { insert = "WATRDran", cat = "WATER", sub = "DRAIN", desc = "Draining gurgling water, pulling in air with it as it drains, think a kitchen sink drain, or a storm drain, shower drain." },
    { insert = "WATRDrip", cat = "WATER", sub = "DRIP", desc = "Water dripping, slow to fast. A cave drip, a leaking pipe dripping or a kitchen faucet dripping." },
    { insert = "WATRFizz", cat = "WATER", sub = "FIZZ", desc = "That sound of Alka-Seltzer in a cup, air fizzing in water. Carbonated beverages." },
    { insert = "WATRFlow", cat = "WATER", sub = "FLOW", desc = "General water flowing, in our case as in a river, creek or stream. Steady water. Rapids would fall under WATER-TURBULENCE, and WATERFALL has its own subcategory" },
    { insert = "WATRFoun", cat = "WATER", sub = "FOUNTAIN", desc = "Water features and fountains, trickles or flows for a fountain, splashy fountains. From tiny to large city fountains." },
    { insert = "WATRImpt", cat = "WATER", sub = "IMPACT", desc = "Percussive water impact, large crash or slam of water, as in huge wave hitting an object. Bigger and sharper than a SPLASH" },
    { insert = "WATRLap", cat = "WATER", sub = "LAP", desc = "Water splashing against something like against the side of a boat or canoe, or a dock. Also meant for very small waves lapping on shore, like gentle very small waves at night." },
    { insert = "WATRMisc", cat = "WATER", sub = "MISC", desc = "Water sounds not fitting another category in this list." },
    { insert = "WATRMvmt", cat = "WATER", sub = "MOVEMENT", desc = "Movement in water but not underwater (see WATER-UNDERWATER) Drags through water, swimming movements, sweeps of objects through water. Thrashing in water." },
    { insert = "WATRPlmb", cat = "WATER", sub = "PLUMBING", desc = "Household plumbing, like a sink running, a toilet flush, the shower running. DRAIN has its own subcategory." },
    { insert = "WATRPour", cat = "WATER", sub = "POUR", desc = "Pouring water, onto ground, into a cup. Overlap with FOOD & DRINK-POUR." },
    { insert = "WATRSplsh", cat = "WATER", sub = "SPLASH", desc = "Water splashes of all kind, a person diving into a pool, a whale cresting, throwing a rock into water." },
    { insert = "WATRSpray", cat = "WATER", sub = "SPRAY", desc = "Big sprays of a wave crash, to a hose spray." },
    { insert = "WATRStm", cat = "WATER", sub = "STEAM", desc = "Very wet hisses, radiators, saunas. Hot wet steam." },
    { insert = "WATRSurf", cat = "WATER", sub = "SURF", desc = "The general roar of the ocean, not the sport. Constant ocean roaring waves." },
    { insert = "WATRTurb", cat = "WATER", sub = "TURBULENT", desc = "Very big splashy water. Whirlpools, big rapids on a river. Dangerous water." },
    { insert = "WATRUndwtr", cat = "WATER", sub = "UNDERWATER", desc = "Specifically underwater sounds, flows, current and movement, Swimming underwater. See also AMBIENCE-UNDERWATER and WATER-MOVEMENT as well." },
    { insert = "WATRFall", cat = "WATER", sub = "WATERFALL", desc = "Waterfalls from small cascading ones to Niagara falls." },
    { insert = "WATRWave", cat = "WATER", sub = "WAVE", desc = "For general water waves, distinct waves. General ocean roar to go in WATER-SURF, and tiny waves to WATER-LAPPING. See also NATURAL DISASTERS-TSUNAMI." },
    { insert = "WEAPArmr", cat = "WEAPONS", sub = "ARMOR", desc = "Knights armor movement, hits. Shields, chainmail armor, leather armor with buckles." },
    { insert = "WEAPArro", cat = "WEAPONS", sub = "ARROW", desc = "Arrow slides, arrow impacts. An arrow by would likely be a SWOOSHES-SWISH. See also WEAPONS-BOW." },
    { insert = "WEAPAxe", cat = "WEAPONS", sub = "AXE", desc = "Specifically a weaponized ax. Possible overlap with WEAPONS-SWORD or even WEAPON-POLEARM." },
    { insert = "WEAPBlnt", cat = "WEAPONS", sub = "BLUNT", desc = "Blunt weapons, like maces and flails, but also nightsticks." },
    { insert = "WEAPBow", cat = "WEAPONS", sub = "BOW", desc = "Bows and Crossbows, articulation, twangs, bolts being loaded. Bow releases. See also WEAPON-ARROW." },
    { insert = "WEAPKnif", cat = "WEAPONS", sub = "KNIFE", desc = "Smaller knives, WEAPONS-SWORDS has it own subcategory here." },
    { insert = "WEAPMisc", cat = "WEAPONS", sub = "MISC", desc = "Weapon sounds not fitting another category in this list." },
    { insert = "WEAPPole", cat = "WEAPONS", sub = "POLEARM", desc = "A long spear or long poled weapon with sharp components at the end, like a harpoon." },
    { insert = "WEAPSiege", cat = "WEAPONS", sub = "SIEGE", desc = "A siege weapon is a device designed to break or circumvent fortifications, catapults, trebuchets. Ancient artillery." },
    { insert = "WEAPSwrd", cat = "WEAPONS", sub = "SWORD", desc = "Swords, clashing, parrying. Sword rings and hits. STABS would go to GORE category. Sword draws, shings." },
    { insert = "WEAPWhip", cat = "WEAPONS", sub = "WHIP", desc = "Whip cracks. Make Indiana Jones proud." },
    { insert = "HAIL", cat = "WEATHER", sub = "HAIL", desc = "Hail on various surfaces." },
    { insert = "WTHR", cat = "WEATHER", sub = "MISC", desc = "Weather sounds not fitting another category in this list. See also NATURAL DISASTER category." },
    { insert = "STORM", cat = "WEATHER", sub = "STORM", desc = "Composite storms, wind, rain, thunder, where elements aren't isolated. Mixed storm composite recordings. Also see WIND-TURBULENT for wind only elements and NATURAL-DISASTER." },
    { insert = "THUN", cat = "WEATHER", sub = "THUNDER", desc = "Thunder and lightning, dry, wet, distant rumbles to sharp thunder cracks. Combination RAIN & THUNDER may best go into WEATHER-STORM" },
    { insert = "WHSTHmn", cat = "WHISTLES", sub = "HUMAN", desc = "Human whistles, wolf-whistles. See also CARTOON-WHISTLES." },
    { insert = "WHSTMech", cat = "WHISTLES", sub = "MECHANICAL", desc = "Train whistles, referee whistles, tea pot whistles, etc, any whistle not made by a human." },
    { insert = "WHSTMisc", cat = "WHISTLES", sub = "MISC", desc = "Whistle sounds not fitting another category in this list." },
    { insert = "WINDDsgn", cat = "WIND", sub = "DESIGNED", desc = "Designed or manufactured or artificial winds, wind machines, synth winds." },
    { insert = "WIND", cat = "WIND", sub = "GENERAL", desc = "Base and general wind category." },
    { insert = "WINDGust", cat = "WIND", sub = "GUST", desc = "For more singular gusts or buffets, accents to cut into other winds. Usually shorter. A constant buffeting wind better off in the GENERAL or TURBULENT category." },
    { insert = "WINDInt", cat = "WIND", sub = "INTERIOR", desc = "Interior wind, through window, or crack in door. Wind through chimney or vent pipe, but see also WIND-TONAL for overtly tonal winds and whistles." },
    { insert = "WINDTonl", cat = "WIND", sub = "TONAL", desc = "Wind howls, wind in wires, wind whistles, overtly tonal winds." },
    { insert = "WINDTurb", cat = "WIND", sub = "TURBULENT", desc = "Extremely violent wind, big buffeting, huge storm winds. Possible overlap with NATURAL DISASTER-TORNADO or WEATHER-STORM." },
    { insert = "WINDVege", cat = "WIND", sub = "VEGETATION", desc = "Wind through foliage, vegetation, grass, trees, leaves, plants." },
    { insert = "WNDWCover", cat = "WINDOWS", sub = "COVERING", desc = "Window curtains, blinds, shutters. So a window covering, not the window itself." },
    { insert = "WNDWHdwr", cat = "WINDOWS", sub = "HARDWARE", desc = "Window latches, cranks, locks. Window hardware." },
    { insert = "WNDWKnck", cat = "WINDOWS", sub = "KNOCK", desc = "Knocking on various window surfaces, knocking on GLASS." },
    { insert = "WNDWMetl", cat = "WINDOWS", sub = "METAL", desc = "Metal framed windows, open and close." },
    { insert = "WNDWMisc", cat = "WINDOWS", sub = "MISC", desc = "Window sounds not fitting another category in this list." },
    { insert = "WNDWPlas", cat = "WINDOWS", sub = "PLASTIC", desc = "Plastic framed windows, plexiglass windows. Vinyl framed windows, open and close." },
    { insert = "WNDWWood", cat = "WINDOWS", sub = "WOOD", desc = "Wood framed windows, open and close." },
    { insert = "WINGBird", cat = "WINGS", sub = "BIRD", desc = "Bird wing flaps, hummingbirds, pigeon wings. Group or single." },
    { insert = "WINGCrea", cat = "WINGS", sub = "CREATURE", desc = "Dragon wings, fairy wings, any manner of creature and monster wings." },
    { insert = "WINGInsc", cat = "WINGS", sub = "INSECT", desc = "Fly and bee wings, dragonflies, moths, butterflies. Any insect wings. Some overlap and confusion with ANIMALS-INECTS likely." },
    { insert = "WINGMisc", cat = "WINGS", sub = "MISC", desc = "Wing sounds not fitting another category in this list." },
    { insert = "WOODBrk", cat = "WOOD", sub = "BREAK", desc = "Wood breaks, shatters, cracks, crunches. Any destruction of wood that breaks the piece." },
    { insert = "WOODCrsh", cat = "WOOD", sub = "CRASH & DEBRIS", desc = "Group wood crashes and debris, and pieces falling, as in after an explosion." },
    { insert = "WOODFric", cat = "WOOD", sub = "FRICTION", desc = "Wood stress, especially creaks. But also scrapes, squeaks." },
    { insert = "WOODHndl", cat = "WOOD", sub = "HANDLE", desc = "Handling a wooden object, picking up, setting down, etc. Some overlap or confusion with WOOD-MOVEMENT." },
    { insert = "WOODImpt", cat = "WOOD", sub = "IMPACT", desc = "Singular wood hits, drops, impacts, board hits. Group wood destruction goes into CRASH. Resonant wood bonks or hits. Hitting your head on a doorframe." },
    { insert = "WOODMisc", cat = "WOOD", sub = "MISC", desc = "Wood sounds not fitting another category in this list." },
    { insert = "WOODMvmt", cat = "WOOD", sub = "MOVEMENT", desc = "Wood movement including rattles, drag, slides, rolls. Group pieces of wood moving together." },
    { insert = "WOODTonl", cat = "WOOD", sub = "TONAL", desc = "Tonal bowed wood sounds, ringing wood." }
